INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('39ec4da3-1181-520f-b4cc-ec1e38558a82', 'ad164887-6583-5303-855e-4183884bca6f', '0d5e5f90-e744-5bf2-a1f5-4f1286e22897', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Nationality', 'Nationality. applicable identity/compliance processes. not Party identity. process-specific. optional. Up to 2 characters.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
