INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8f56789e-7fa7-5449-9558-a2860d09f02f', 'Account', 'Maintain Account records', 'Create, find and maintain Account records. The list shows every Account you have access to — select a row to open it, or use New to add one. Each row is a single Account, described by 8 fields.

Id is unique: no two Account records may share the same value, and a save that would duplicate one is rejected. Code, Name, Account Type and Status must be filled in before the record can be saved.

Every Account points at Currency and Organization. Choose the linked record from the lookup on those fields rather than typing an identifier. Journal Entry Line and Budget Line refer back to Account, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Account then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Account with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b1507289-b12c-52bd-a713-ae1175199f23', 'bus_account', 'Account', 'Represents a financial master entity called Account within the CEDM business model. Account is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate Account records. The entity participates in a wider business graph through relationships with Account, Account, Organization. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical Account record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '8f56789e-7fa7-5449-9558-a2860d09f02f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('32997f2f-78e8-50b0-8e20-fc39f3729c58', '8f56789e-7fa7-5449-9558-a2860d09f02f', 'b1507289-b12c-52bd-a713-ae1175199f23', 'Account', 'Shows one Account at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency and Organization are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4fbeeac4-c49f-5da2-b063-06a5b783f56f', 'b1507289-b12c-52bd-a713-ae1175199f23', 'id', 'Id', 'Identifies the account record associated with this Account. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Account records, where applicable. Its meaning is specific to Account; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81322f04-c05e-5b4e-bad5-223589a074d7', 'b1507289-b12c-52bd-a713-ae1175199f23', 'code', 'Code', 'A human-readable business code used to identify or reference the record in operational processes and integrations. Used when creating, reviewing, searching, validating, reporting on, or integrating Account records, where applicable. Its meaning is specific to Account; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
