VALUES ('046ba29c-df7e-587b-a12e-1962bd7fa64b', '32997f2f-78e8-50b0-8e20-fc39f3729c58', 'e0510fe6-60cc-5eba-a756-756fe275ad26', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Currency', 'Identifies the currency in which monetary amounts on the record are expressed, allowing amounts to be interpreted and aggregated consistently. Used when creating, reviewing, searching, validating, reporting on, or integrating Account records, where applicable. This field connects Account to Currency. The reference establishes business context between the two entities and lets processes navigate from this record to the related Currency. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3f1537e0-5e50-511f-a717-97f31692bc51', '32997f2f-78e8-50b0-8e20-fc39f3729c58', '0ab764e7-52a6-5dd4-a1ec-73b6f7ed5790', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Parent Account', 'Connects Account to Account so related business context can be navigated and enforced. Used when processes need to find or reason about Account records associated with a Account. The declared cardinality 0..1 expresses how many related records may participate in the relationship. The relationship is part of the CEDM semantic graph and is interpreted together with source and target entities, ownership, conditions, and invariants.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
