VALUES ('48cd7940-759d-5e99-8391-c2f22594508a', '878be901-080d-55e8-b777-413d10f02110', 'organization_id', 'Organization', 'Organization whose books recognize the accounting entry. Supports legal-entity accounting, reporting, period control and ledger ownership. Optional when organization is inherited from ledger context. Determines accounting boundary and applicable chart/period policies.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
