INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6b517bc-8891-5d08-bdd4-3bb5020b6cbe', 'Journal Entry Line', 'Maintain Journal Entry Line records', 'Create, find and maintain Journal Entry Line records. The list shows every Journal Entry Line you have access to — select a row to open it, or use New to add one. Each row is a single Journal Entry Line, described by 7 fields.

Id is unique: no two Journal Entry Line records may share the same value, and a save that would duplicate one is rejected. Line Number, Debit Amount, Credit Amount, Journal Entry and Account must be filled in before the record can be saved.

Every Journal Entry Line points at Journal Entry and Account. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Journal Entry Line then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Journal Entry Line with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('88ce57b5-83fc-5749-9e7e-104a138bfb57', 'bus_journal_entry_line', 'Journal Entry Line', 'Represents a financial transaction line called JournalEntryLine within the CEDM business model. JournalEntryLine is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate JournalEntryLine records. The entity participates in a wider business graph through relationships with JournalEntry, Account. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical JournalEntryLine record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, 'd6b517bc-8891-5d08-bdd4-3bb5020b6cbe', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9418f3dd-ee9b-543a-b8fd-32ede7d19dfc', 'd6b517bc-8891-5d08-bdd4-3bb5020b6cbe', '88ce57b5-83fc-5749-9e7e-104a138bfb57', 'Journal Entry Line', 'Shows one Journal Entry Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Journal Entry and Account are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
