ON CONFLICT DO NOTHING;
INSERT INTO sys_access (sys_access_id, sys_role_id, sys_table_id, sys_window_id, access_type_table, is_read_only, is_exclude, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5e966835-55cd-55fe-b366-1e29c22704ca', (SELECT sys_role_id FROM sys_role WHERE name = 'User'), '7e027db7-da5e-5d7c-b9c3-282e8f867fd8', 'ec10cbd8-599c-599c-80e9-70e006cd6747', 'R', TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
