VALUES ('f081c719-acf3-5663-a302-67f993e4509d', 'c4879151-d97c-5f16-b081-474640db365e', 'party_role_id', 'Party Role', 'PartyRole backing the Supplier specialization. Navigates to common party identity and role information. Supplier must not duplicate Party identity. Supplies shared party context to procurement and financial workflows. Required for role specialization.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
