VALUES ('dcc76c8a-e05c-5ffb-89c8-b7eb848aa0fc', 'c4879151-d97c-5f16-b081-474640db365e', 'customer_role_id', 'Customer Role', 'Optional role specialization corresponding to the roleType. Connects generic PartyRole identity to role-specific business controls such as customer credit or supplier qualification. At most one specialization is represented by this relationship in the current core model. Allows specialized workflows to extend the role without duplicating Party identity.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c8ee588a-7d51-5a6f-8531-efd338e83ef7', 'c4879151-d97c-5f16-b081-474640db365e', 'supplier_role_id', 'Supplier Role', 'Links the generic PartyRole to the specialized Supplier role record when applicable. Provides direct navigation from role assignment to specialized supplier commercial data. Optional because not every PartyRole represents a supplier. Connects supplier-role eligibility to governed procurement and supplier-management workflows.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
