VALUES ('aabc4ffd-f4be-57fb-a7af-bc3ec7676d88', '942a3485-c189-531c-9889-b8cf580daa79', 'supplier_role_id', 'Supplier Role', 'Links the generic PartyRole to the specialized Supplier role record when applicable. Provides direct navigation from role assignment to specialized supplier commercial data. Optional because not every PartyRole represents a supplier. Connects supplier-role eligibility to governed procurement and supplier-management workflows.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 160, 'U', TRUE, 'system', 'system', NOW(), NOW())
