VALUES ('465a076a-5131-5225-9dd7-fe3a2d592579', 'fcab9907-6866-59c7-be62-b7268427e7a8', '76930899-2220-58ae-b448-817c1bc97393', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'Stable identifier for the Customer business relationship. Used by orders invoices receivables service pricing credit contracts and analytics. Party identifies the underlying party while customerId identifies the customer relationship. Provides the stable customer reference carried into SalesOrder Invoice Payment shipment service and receivables workflows. Required for unambiguous customer transaction traceability. Must be unique: a save is rejected if another Customer already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8a06895f-a76c-5700-9758-7aa5eab5e926', 'fcab9907-6866-59c7-be62-b7268427e7a8', 'cfa773cf-fa22-5245-8ba5-875ad3511ffa', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Party Role', 'Links Customer to its underlying PartyRole. Resolves common party identity and role information. Customer is a role specialization and must not duplicate Party identity. Supplies common party context to customer-facing workflows. Required because Customer depends on PartyRole. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Customer already uses this value.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1e374f8d-821d-5952-86f7-ca74b3fd2fe7', 'fcab9907-6866-59c7-be62-b7268427e7a8', 'dd3bd1c4-fc1d-5e81-a173-05b2fc986188', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Customer Code', 'Human-facing customer business code. Used in orders invoices statements integrations and communication. Distinct from customerId and external legal identifiers. Supports customer selection and transaction recognition. Required for operational identification. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Customer already uses this value. Up to 100 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
