INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('88ec5c7a-a6fe-5f7b-aab3-a8badfedeaa6', 'Budget', 'Maintain Budget records', 'Create, find and maintain Budget records. The list shows every Budget you have access to — select a row to open it, or use New to add one. Each row is a single Budget, described by 6 fields.

Id is unique: no two Budget records may share the same value, and a save that would duplicate one is rejected. Code, Status and Organization must be filled in before the record can be saved.

Every Budget points at Organization, Fiscal Period and Scenario. Choose the linked record from the lookup on those fields rather than typing an identifier. Budget Line and Variance refer back to Budget, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Budget then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Budget with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'bus_budget', 'Budget', 'Governed financial planning baseline. Budget records intended/authorized financial amounts while JournalEntry records actual accounting. Planning, spending control and variance reporting. BudgetLine supplies dimensional detail; FiscalPeriod supplies accounting time; Scenario supplies planning assumptions. Draft to submitted to approved/active to superseded/closed.', 'A', FALSE, FALSE, FALSE, TRUE, '88ec5c7a-a6fe-5f7b-aab3-a8badfedeaa6', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8080a08e-4d03-5f0e-bd22-325ea8a29b72', '88ec5c7a-a6fe-5f7b-aab3-a8badfedeaa6', 'c9e27f4d-295a-5675-a24c-0ecc0df08c41', 'Budget', 'Shows one Budget at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Organization, Fiscal Period and Scenario are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
