INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f8477c6c-8c47-5ff5-87ad-2b95892df1c0', 'Forecast', 'Maintain Forecast records', 'Create, find and maintain Forecast records. The list shows every Forecast you have access to — select a row to open it, or use New to add one. Each row is a single Forecast, described by 5 fields.

Id is unique: no two Forecast records may share the same value, and a save that would duplicate one is rejected. Code and Organization must be filled in before the record can be saved.

Every Forecast points at Organization, Scenario and Fiscal Period. Choose the linked record from the lookup on those fields rather than typing an identifier. Variance refers back to Forecast, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Forecast then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Forecast with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2f5b3405-aaeb-5089-8ddd-9303da090940', 'bus_forecast', 'Forecast', 'A versioned forward-looking financial projection based on a defined scenario and as-of information, kept separate from approved budgets and actual accounting. Provides planning/management semantics separately from actual accounting evidence. Planning, control, management reporting and analysis. Organization supplies governance; financial transactions remain authoritative for actuals.', 'A', FALSE, FALSE, FALSE, TRUE, 'f8477c6c-8c47-5ff5-87ad-2b95892df1c0', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
