INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('398d695f-dd11-56f0-b24b-1da410533803', 'Ledger', 'Maintain Ledger records', 'Create, find and maintain Ledger records. The list shows every Ledger you have access to — select a row to open it, or use New to add one. Each row is a single Ledger, described by 3 fields.

Id is unique: no two Ledger records may share the same value, and a save that would duplicate one is rejected. Status and Organization must be filled in before the record can be saved.

Every Ledger points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier. Journal Entry refers back to Ledger, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Ledger then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Ledger with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('081d6677-2845-5af9-8a12-b5f2286e2f92', 'bus_ledger', 'Ledger', 'A governed accounting book defining the scope in which journal entries are recorded and reported. Provide canonical enterprise semantics for Ledger while keeping planning, operational, financial and evidential responsibilities separated. A governed accounting book defining the scope in which journal entries are recorded and reported. Used by applicable finance, treasury, tax, subscription, billing, reporting and integration workflows. References canonical parties and transactions; downstream accounting and cash effects remain explicit through JournalEntry, Payment and BankTransaction where applicable. Created under governed workflow, progressed through explicit states, and retained historically after completion/cancellation. Financial control, tax, billing, subscription management, settlement, reconciliation and audit. Enterprise finance and recurring-revenue operations.', 'A', FALSE, FALSE, FALSE, TRUE, '398d695f-dd11-56f0-b24b-1da410533803', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e72606ff-99f2-5502-b688-4f8c53542bf8', '398d695f-dd11-56f0-b24b-1da410533803', '081d6677-2845-5af9-8a12-b5f2286e2f92', 'Ledger', 'Shows one Ledger at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Organization is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
