INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1070efe3-e8ab-5e4d-8481-edc5bd5d6cf0', 'Payment Instruction', 'Maintain Payment Instruction records', 'Create, find and maintain Payment Instruction records. The list shows every Payment Instruction you have access to — select a row to open it, or use New to add one. Each row is a single Payment Instruction, described by 4 fields.

Id is unique: no two Payment Instruction records may share the same value, and a save that would duplicate one is rejected. Status and Bank Account must be filled in before the record can be saved.

Every Payment Instruction points at Bank Account and Payment. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Payment Instruction then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Payment Instruction with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e1248040-d883-5206-87cb-3753f03469cc', 'bus_payment_instruction', 'Payment Instruction', 'A governed instruction authorizing or requesting a future payment through a bank or payment channel, separate from the resulting Payment and BankTransaction evidence. Provide canonical enterprise semantics for PaymentInstruction while keeping planning, operational, financial and evidential responsibilities separated. A governed instruction authorizing or requesting a future payment through a bank or payment channel, separate from the resulting Payment and BankTransaction evidence. Used by applicable finance, treasury, tax, subscription, billing, reporting and integration workflows. References canonical parties and transactions; downstream accounting and cash effects remain explicit through JournalEntry, Payment and BankTransaction where applicable. Created under governed workflow, progressed through explicit states, and retained historically after completion/cancellation. Financial control, tax, billing, subscription management, settlement, reconciliation and audit. Enterprise finance and recurring-revenue operations.', 'A', FALSE, FALSE, FALSE, TRUE, '1070efe3-e8ab-5e4d-8481-edc5bd5d6cf0', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
