-- --------------------------------------------------------------------------
-- Credit Note (bus_credit_note)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('88634eaa-67df-5b93-be1e-cab32f218399', 'Credit Note', 'Maintain Credit Note records', 'Create, find and maintain Credit Note records. The list shows every Credit Note you have access to — select a row to open it, or use New to add one. Each row is a single Credit Note, described by 13 fields.

Id and Credit Note Number are unique: no two Credit Note records may share the same value, and a save that would duplicate one is rejected. Credit Note Number, Credit Note Date, Status, Currency, Reason Code, Subtotal, Tax Amount, Total Amount, Amount Applied, Amount Refunded, Amount Remaining and Customer must be filled in before the record can be saved.

Every Credit Note points at Currency and Customer. Choose the linked record from the lookup on those fields rather than typing an identifier. Journal Entry, Credit Note Line and Credit Note Application refer back to Credit Note, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Credit Note then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Credit Note with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'bus_credit_note', 'Credit Note', 'Represents an explicit reduction of a customer''s financial claim while preserving original invoice, return, accounting, application and refund evidence. CustomerReturn records reverse fulfillment; CreditNote records the financial adjustment; CreditNoteApplication records how it is consumed; Invoice remains the historical claim; JournalEntry records accounting; Payment records any refund cash. Customer returns, accounts receivable, billing corrections, tax adjustments, customer concessions, statements, audit and refunds. CustomerReturnLine provides returned quantity and approved credit basis. InvoiceLine provides original billed evidence. CreditNoteLine captures adjustment detail. CreditNoteApplication connects the adjustment to invoice exposure. JournalEntry records accounting. Payment records refund. Return authorized → received/inspected → disposition approved → credit eligibility calculated → CreditNote draft → approval → accounting determination → post → create CreditNoteApplication against open Invoice or establish refund due → refund Payment if required → reconcile → fully applied/refunded. Original Invoice and Payment history remain immutable. Draft → approved → posted → partially applied/fully applied or refund due → refunded, with cancellation and reversal paths. Changes to return disposition or original invoice evidence trigger revalidation of an unposted credit. Posted credit changes require explicit reversal and replacement. Applications are corrected by reversal/reallocation, and refund payments remain separate evidence. A customer returns five units with approved credit of USD 590. CreditNote is posted for USD 590. A CreditNoteApplication can consume the credit against an open invoice; if no eligible balance exists, the credit becomes refund due and a separate Payment settles it.', 'A', FALSE, FALSE, FALSE, TRUE, '88634eaa-67df-5b93-be1e-cab32f218399', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5fcf4ae7-72b6-535a-8310-35fc7040a56e', '88634eaa-67df-5b93-be1e-cab32f218399', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'Credit Note', 'Shows one Credit Note at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 12 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency and Customer are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7d6753fd-83ca-51cb-876b-71892a5396d0', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'id', 'Id', 'Immutable identity of the credit note. Identifies the financial adjustment independently of its business number, original invoice, return, accounting entry, application or refund. Used for audit, accounting, customer statements, integrations, reconciliation, tax and reversal workflows. CreditNoteId is the stable system identity; creditNoteNumber is the business-facing reference; the original Invoice remains a separate historical claim. Root reference across preparation, approval, posting, application, reversal, reporting and refund processing. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('67f5a6b2-0063-5c9c-82b7-5a9ebb66b31c', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'credit_note_number', 'Credit Note Number', 'Business-facing reference assigned to the credit note. Identifies the adjustment in customer communication, tax documents, statements and finance operations. Used for reconciliation, customer service, reporting, tax and integrations. Distinct from creditNoteId and original Invoice.invoiceNumber. Provides the human-recognizable adjustment reference throughout its lifecycle. Required.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('48f68382-2655-5241-b079-ca41146b01b3', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'credit_note_date', 'Credit Note Date', 'Commercial and accounting date of the credit adjustment. Establishes the temporal basis for accounting, tax and customer balance treatment. Used for accounting periods, tax reporting, statements and audit. May differ from CustomerReturn returnDate and refund payment date. Anchors the financial adjustment in the applicable accounting and tax period. Required.', 15, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('70744929-9c2a-5419-924b-45947d8fd540', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'status', 'Status', 'Lifecycle state of the credit adjustment. Indicates preparation, authorization, accounting recognition, application to invoices, customer refund obligation, settlement, cancellation or reversal. Controls approval, posting, application, refund and correction workflows. CreditNote status is independent of Invoice, CustomerReturn, Payment and CreditNoteApplication status. POSTED establishes the financial adjustment; application reduces eligible outstanding receivable; refund states apply when money must be returned. Required.', 1012, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a4fc341e-7222-5973-a0db-876d9d32247d', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'currency_id', 'Currency', 'Currency in which the credit note is denominated. Defines the monetary denomination of all credit-note amounts. Used for calculation, tax, accounting, invoice application, customer balance and refund processing. Must normally match credited Invoice currency; permitted cross-currency application requires explicit ExchangeRate evidence. Establishes monetary basis for adjustment and application. Required.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('52951a36-49f7-54ea-85e8-bca8dd981ace', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'reason_code', 'Reason Code', 'Controlled business reason for issuing the credit. Explains why customer exposure is reduced. Used for approval, policy, analytics, tax, audit and customer communication. Return reason and financial credit reason may differ. Determines applicable approval, calculation, tax and posting policy. Required.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('352637e2-db1e-5525-bab6-0de988ad9bc3', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'subtotal', 'Subtotal', 'Aggregate credit value before document-level tax and adjustments. Sum of credit-note line bases after applicable line pricing treatment. Used for tax, reconciliation, accounting and reporting. Must reconcile with CreditNoteLine amounts and original transaction evidence. Feeds taxable amount and total credit calculation. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a2f6876f-3c69-5e80-b566-dd944b2765b6', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'tax_amount', 'Tax Amount', 'Tax component reversed or credited by the adjustment. Represents tax reduction associated with credited transaction. Used for tax reporting, accounting and reconciliation. Must reconcile with CreditNoteLine tax evidence and original InvoiceLine treatment where applicable. Contributes to total adjustment. Required, including zero.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ebf6fce2-fbd0-50d2-830d-a470fd47aeca', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'total_amount', 'Total Amount', 'Total monetary reduction represented by the credit note. Amount by which eligible customer exposure is reduced before application or refund settlement. Used for receivable adjustment, statements, tax, accounting, application and refund decisions. Not itself a cash refund; refund requires a separate Payment event. Maximum amount that can be applied or refunded under policy. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('15f2cde4-e843-58f9-8708-b05428322879', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'amount_applied', 'Amount Applied', 'Portion of the posted credit note already applied to eligible invoice balances. Represents non-cash use of the credit to reduce receivable exposure. Used for application status, statements and remaining credit calculation. Must reconcile with active CreditNoteApplication records. Changes through controlled application or reversal workflows. Required as a settlement projection.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ba51c05f-6074-52af-ad5a-a219c583031c', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'amount_refunded', 'Amount Refunded', 'Portion of the credit actually paid back to the customer. Represents cash settlement of customer credit. Used for refund reconciliation, customer balance and audit. Must reconcile with refund Payment evidence. Changes only after an authorized refund Payment is posted and linked. Required as a refund projection.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('03123831-f36b-52d4-8455-5ef4ebf6b631', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'amount_remaining', 'Amount Remaining', 'Unapplied and unrefunded portion of the posted credit. Represents remaining customer credit exposure available for application or refund. Drives application, refund and reconciliation decisions. Reconciles totalAmount against active application and refund evidence. Determines whether further application or refund is permitted. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7645880b-aa76-5068-8f88-f69282292c95', 'cb1334f2-b079-5c0a-8cbb-8dff2bace3c6', 'customer_id', 'Customer', 'Customer whose financial exposure is reduced. Identifies party receiving financial benefit. Supports statements, receivables, approval, tax, refund and audit. Provides customer eligibility and settlement context.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('79a07dcc-ba5f-5176-87a1-c3fd826caf4b', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '7d6753fd-83ca-51cb-876b-71892a5396d0', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'Immutable identity of the credit note. Identifies the financial adjustment independently of its business number, original invoice, return, accounting entry, application or refund. Used for audit, accounting, customer statements, integrations, reconciliation, tax and reversal workflows. CreditNoteId is the stable system identity; creditNoteNumber is the business-facing reference; the original Invoice remains a separate historical claim. Root reference across preparation, approval, posting, application, reversal, reporting and refund processing. Required. Must be unique: a save is rejected if another Credit Note already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e83cc201-4416-5b2e-b8ff-1cb05a38198b', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '67f5a6b2-0063-5c9c-82b7-5a9ebb66b31c', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Credit Note Number', 'Business-facing reference assigned to the credit note. Identifies the adjustment in customer communication, tax documents, statements and finance operations. Used for reconciliation, customer service, reporting, tax and integrations. Distinct from creditNoteId and original Invoice.invoiceNumber. Provides the human-recognizable adjustment reference throughout its lifecycle. Required. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Credit Note already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7ff889d8-488a-5e09-ad72-d8facb1cb46a', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '48f68382-2655-5241-b079-ca41146b01b3', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Credit Note Date', 'Commercial and accounting date of the credit adjustment. Establishes the temporal basis for accounting, tax and customer balance treatment. Used for accounting periods, tax reporting, statements and audit. May differ from CustomerReturn returnDate and refund payment date. Anchors the financial adjustment in the applicable accounting and tax period. Required. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a645d99b-b4bb-57cf-b1bf-d585cb11f919', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '70744929-9c2a-5419-924b-45947d8fd540', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Status', 'Lifecycle state of the credit adjustment. Indicates preparation, authorization, accounting recognition, application to invoices, customer refund obligation, settlement, cancellation or reversal. Controls approval, posting, application, refund and correction workflows. CreditNote status is independent of Invoice, CustomerReturn, Payment and CreditNoteApplication status. POSTED establishes the financial adjustment; application reduces eligible outstanding receivable; refund states apply when money must be returned. Required. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2611a002-9b0d-5c19-9d70-282afee40666', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', 'a4fc341e-7222-5973-a0db-876d9d32247d', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Currency', 'Currency in which the credit note is denominated. Defines the monetary denomination of all credit-note amounts. Used for calculation, tax, accounting, invoice application, customer balance and refund processing. Must normally match credited Invoice currency; permitted cross-currency application requires explicit ExchangeRate evidence. Establishes monetary basis for adjustment and application. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0398b4bb-5503-5c27-9ac9-09207ee5e643', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '52951a36-49f7-54ea-85e8-bca8dd981ace', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Reason Code', 'Controlled business reason for issuing the credit. Explains why customer exposure is reduced. Used for approval, policy, analytics, tax, audit and customer communication. Return reason and financial credit reason may differ. Determines applicable approval, calculation, tax and posting policy. Required. Required — the record cannot be saved while this is empty. Up to 100 characters.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('854fd6b1-b1ce-5d5c-818a-db8f5db39e3d', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '352637e2-db1e-5525-bab6-0de988ad9bc3', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Subtotal', 'Aggregate credit value before document-level tax and adjustments. Sum of credit-note line bases after applicable line pricing treatment. Used for tax, reconciliation, accounting and reporting. Must reconcile with CreditNoteLine amounts and original transaction evidence. Feeds taxable amount and total credit calculation. Required. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('112dfbe9-0a78-5295-bcac-bc4703a1361c', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', 'a2f6876f-3c69-5e80-b566-dd944b2765b6', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Tax Amount', 'Tax component reversed or credited by the adjustment. Represents tax reduction associated with credited transaction. Used for tax reporting, accounting and reconciliation. Must reconcile with CreditNoteLine tax evidence and original InvoiceLine treatment where applicable. Contributes to total adjustment. Required, including zero. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('211eede7-1de2-53f6-9b65-02ae698ee601', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', 'ebf6fce2-fbd0-50d2-830d-a470fd47aeca', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Total Amount', 'Total monetary reduction represented by the credit note. Amount by which eligible customer exposure is reduced before application or refund settlement. Used for receivable adjustment, statements, tax, accounting, application and refund decisions. Not itself a cash refund; refund requires a separate Payment event. Maximum amount that can be applied or refunded under policy. Required. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4130be8e-14bb-53de-ae9d-a2291980fc01', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '15f2cde4-e843-58f9-8708-b05428322879', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Amount Applied', 'Portion of the posted credit note already applied to eligible invoice balances. Represents non-cash use of the credit to reduce receivable exposure. Used for application status, statements and remaining credit calculation. Must reconcile with active CreditNoteApplication records. Changes through controlled application or reversal workflows. Required as a settlement projection. Required — the record cannot be saved while this is empty.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('df6cf1f0-0e12-585a-be5a-19b1a243f1ce', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', 'ba51c05f-6074-52af-ad5a-a219c583031c', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Amount Refunded', 'Portion of the credit actually paid back to the customer. Represents cash settlement of customer credit. Used for refund reconciliation, customer balance and audit. Must reconcile with refund Payment evidence. Changes only after an authorized refund Payment is posted and linked. Required as a refund projection. Required — the record cannot be saved while this is empty.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3411db6c-b8b4-5341-a9b5-a25132da3c72', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '03123831-f36b-52d4-8455-5ef4ebf6b631', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Amount Remaining', 'Unapplied and unrefunded portion of the posted credit. Represents remaining customer credit exposure available for application or refund. Drives application, refund and reconciliation decisions. Reconciles totalAmount against active application and refund evidence. Determines whether further application or refund is permitted. Required. Required — the record cannot be saved while this is empty.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81ad449b-3d9d-52a3-b726-a7d45cf9385f', '5fcf4ae7-72b6-535a-8310-35fc7040a56e', '7645880b-aa76-5068-8f88-f69282292c95', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Customer', 'Customer whose financial exposure is reduced. Identifies party receiving financial benefit. Supports statements, receivables, approval, tax, refund and audit. Provides customer eligibility and settlement context. Required — the record cannot be saved while this is empty.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
