INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('30640d82-f863-527c-9056-090ac0d6e66d', 'Tax Code', 'Maintain Tax Code records', 'Create, find and maintain Tax Code records. The list shows every Tax Code you have access to — select a row to open it, or use New to add one. Each row is a single Tax Code, described by 3 fields.

Id is unique: no two Tax Code records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Tax Code points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tax Code then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tax Code with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a49b266-ca2f-5fd7-aeca-411ee3350bf7', 'bus_tax_code', 'Tax Code', 'A governed tax classification code used to select applicable tax rules, rates, jurisdictions, registrations, and reporting treatment. Provide canonical enterprise semantics for TaxCode while keeping planning, operational, financial and evidential responsibilities separated. A governed tax classification code used to select applicable tax rules, rates, jurisdictions, registrations, and reporting treatment. Used by applicable finance, treasury, tax, subscription, billing, reporting and integration workflows. References canonical parties and transactions; downstream accounting and cash effects remain explicit through JournalEntry, Payment and BankTransaction where applicable. Created under governed workflow, progressed through explicit states, and retained historically after completion/cancellation. Financial control, tax, billing, subscription management, settlement, reconciliation and audit. Enterprise finance and recurring-revenue operations.', 'A', FALSE, FALSE, FALSE, TRUE, '30640d82-f863-527c-9056-090ac0d6e66d', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('36a074b8-283f-5026-b3e6-2536e42b24b3', '30640d82-f863-527c-9056-090ac0d6e66d', '4a49b266-ca2f-5fd7-aeca-411ee3350bf7', 'Tax Code', 'Shows one Tax Code at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Organization is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
