INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b9c7553d-7607-5fd2-b4e8-2d5df50b5ffa', 'Tax Rate', 'Maintain Tax Rate records', 'Create, find and maintain Tax Rate records. The list shows every Tax Rate you have access to — select a row to open it, or use New to add one. Each row is a single Tax Rate, described by 3 fields.

Id is unique: no two Tax Rate records may share the same value, and a save that would duplicate one is rejected. Status must be filled in before the record can be saved.

Every Tax Rate points at Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Tax Rate then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Tax Rate with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2ec8c24f-25e6-5f7a-bd23-ce5d370ad306', 'bus_tax_rate', 'Tax Rate', 'A governed effective-dated tax percentage or amount applicable under a TaxCode and TaxJurisdiction. Provide canonical enterprise semantics for TaxRate while keeping planning, operational, financial and evidential responsibilities separated. A governed effective-dated tax percentage or amount applicable under a TaxCode and TaxJurisdiction. Used by applicable finance, treasury, tax, subscription, billing, reporting and integration workflows. References canonical parties and transactions; downstream accounting and cash effects remain explicit through JournalEntry, Payment and BankTransaction where applicable. Created under governed workflow, progressed through explicit states, and retained historically after completion/cancellation. Financial control, tax, billing, subscription management, settlement, reconciliation and audit. Enterprise finance and recurring-revenue operations.', 'A', FALSE, FALSE, FALSE, TRUE, 'b9c7553d-7607-5fd2-b4e8-2d5df50b5ffa', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
