VALUES ('c16ac666-5348-5495-8115-f8e441649b45', '0b038c7a-bce7-513d-b36c-533e35baba51', 'b2e8aa43-e745-5e12-aeaa-ab5584364109', 'Subscription', 'Shows one Subscription at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Customer is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
