INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3afe8127-a910-5766-a553-d34a780cef72', '9f6e37ef-c4ec-508b-afb0-bc192c4fa054', '8fd4a636-ae76-563c-8ef1-d30ae599b6a9', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Net Book Value', 'The asset''s carrying amount after recognized depreciation and other applicable accounting adjustments under this schedule. Used for balance-sheet reporting, disposal analysis, impairment assessment, management reporting, and asset valuation. Net book value is an accounting measure and should not be interpreted as market sale value, repair-adjusted value, or predicted disposition value. Optional when carrying value is calculated on demand from the asset''s accounting history rather than stored.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('181b0c47-e515-5165-b680-48fb20e1b0a0', '9f6e37ef-c4ec-508b-afb0-bc192c4fa054', '1bf06266-432d-59b5-95f4-6954c2c6a5db', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Asset', 'Identifies the individual Asset whose financial depreciation is being measured. Connects depreciation calculations to the asset''s acquisition, lifecycle, ownership, maintenance, and disposal history. Exactly one Asset is measured by a depreciation record. Asset is the physical/accountable resource; AssetDepreciation is the financial measurement of that resource. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6405d5ca-d74a-5cfc-ab8f-c6cd7330baa0', '9f6e37ef-c4ec-508b-afb0-bc192c4fa054', 'febd200d-c021-57e1-bd5e-6a0d37f426e8', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Product', 'Identifies the standardized product or equipment definition relevant to the depreciated asset. Supports fleet/class-level depreciation analysis, equipment reporting, and policy assignment. Zero or one Product may be linked when depreciation policy is associated with a product class or model. Product describes the reusable model; depreciation remains attached to the individual Asset and its accounting context.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e54105ab-18f6-512b-92ee-01e80aeed616', '9f6e37ef-c4ec-508b-afb0-bc192c4fa054', '75b5339a-78f6-5e8d-817f-81dc69284ae2', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Currency', 'Identifies the currency in which monetary depreciation values are expressed. Used to interpret depreciable base, accumulated depreciation, salvage value, and net book value in financial reporting. Zero or one Currency may be linked when currency is inherited from the accounting ledger or financial context. Currency gives monetary values their denomination and does not define the depreciation method or asset identity.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
