-- --------------------------------------------------------------------------
-- Asset Disposal (bus_asset_disposal)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cce8c3ec-18d1-5e18-973e-7db188ba35aa', 'Asset Disposal', 'Maintain Asset Disposal records', 'Create, find and maintain Asset Disposal records. The list shows every Asset Disposal you have access to — select a row to open it, or use New to add one. Each row is a single Asset Disposal, described by 3 fields.

Id is unique: no two Asset Disposal records may share the same value, and a save that would duplicate one is rejected. Asset must be filled in before the record can be saved.

Every Asset Disposal points at Asset. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Asset Disposal then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Asset Disposal with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd06b9ba-9532-5eb6-959c-bfe8da27fecd', 'bus_asset_disposal', 'Asset Disposal', 'A governed event retiring, selling, scrapping, or otherwise disposing of an Asset with auditable operational and accounting consequences. Provide canonical enterprise semantics for AssetDisposal. A governed event retiring, selling, scrapping, or otherwise disposing of an Asset with auditable operational and accounting consequences. Used in asset, maintenance, treasury, banking, credit-risk, accounting, integration, and audit workflows where applicable. Connects operational or financial lifecycle evidence to canonical masters while keeping accounting, bank, and physical records authoritative in their own domains. Created under governed conditions, progressed or finalized with audit history, and corrected through explicit subsequent evidence. Asset lifecycle, maintenance, treasury operations, bank reconciliation, lending, accounting, reporting, and audit. Enterprise fixed assets, equipment reliability, bank close, FX, deposits, interest, and secured lending.', 'A', FALSE, FALSE, FALSE, TRUE, 'cce8c3ec-18d1-5e18-973e-7db188ba35aa', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7ab0ecd6-4fbf-59c0-80d0-daf4f4775091', 'cce8c3ec-18d1-5e18-973e-7db188ba35aa', 'fd06b9ba-9532-5eb6-959c-bfe8da27fecd', 'Asset Disposal', 'Shows one Asset Disposal at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Asset is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
