-- --------------------------------------------------------------------------
-- Foreign Exchange Transaction (bus_foreign_exchange_transaction)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0eaac3e9-5f4d-5220-84d8-033c8080e171', 'Foreign Exchange Transaction', 'Maintain Foreign Exchange Transaction records', 'Create, find and maintain Foreign Exchange Transaction records. The list shows every Foreign Exchange Transaction you have access to — select a row to open it, or use New to add one. Each row is a single Foreign Exchange Transaction, described by 2 fields.

Id is unique: no two Foreign Exchange Transaction records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Foreign Exchange Transaction then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Foreign Exchange Transaction with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('42380ac1-995d-5fcf-b18d-72368954bfd9', 'bus_foreign_exchange_transaction', 'Foreign Exchange Transaction', 'A governed agreement or execution exchanging one currency for another at defined amounts, rate, dates, and counterparties. Provide canonical enterprise semantics for ForeignExchangeTransaction. A governed agreement or execution exchanging one currency for another at defined amounts, rate, dates, and counterparties. Used in asset, maintenance, treasury, banking, credit-risk, accounting, integration, and audit workflows where applicable. Connects operational or financial lifecycle evidence to canonical masters while keeping accounting, bank, and physical records authoritative in their own domains. Created under governed conditions, progressed or finalized with audit history, and corrected through explicit subsequent evidence. Asset lifecycle, maintenance, treasury operations, bank reconciliation, lending, accounting, reporting, and audit. Enterprise fixed assets, equipment reliability, bank close, FX, deposits, interest, and secured lending.', 'A', FALSE, FALSE, FALSE, TRUE, '0eaac3e9-5f4d-5220-84d8-033c8080e171', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c539df93-db21-50ee-84d3-329f498ebcea', '0eaac3e9-5f4d-5220-84d8-033c8080e171', '42380ac1-995d-5fcf-b18d-72368954bfd9', 'Foreign Exchange Transaction', 'Shows one Foreign Exchange Transaction at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
