INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc2636ab-0e6b-50f1-b2d1-8a01ac81eaed', 'Cash Position', 'Maintain Cash Position records', 'Create, find and maintain Cash Position records. The list shows every Cash Position you have access to — select a row to open it, or use New to add one. Each row is a single Cash Position, described by 6 fields.

Id is unique: no two Cash Position records may share the same value, and a save that would duplicate one is rejected. As Of, Ledger Balance, Available Balance and Bank Account must be filled in before the record can be saved.

Every Cash Position points at Bank Account. Choose the linked record from the lookup on those fields rather than typing an identifier. Payment refers back to Cash Position, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Cash Position then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Cash Position with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd81e359-be3b-5627-a0ba-078b152ffdd8', 'bus_cash_position', 'Cash Position', 'Reproducible point-in-time treasury liquidity view. CashPosition summarizes cash; BankTransaction supplies external evidence, Payment supplies internal settlement state, and JournalEntry supplies accounting recognition. Daily cash management, liquidity, funding, payment planning and treasury reporting. BankAccount defines account/currency; bank transactions and payments supply observed/pending cash evidence. Calculated for an as-of cutoff → reviewed/published where required → retained or superseded by later snapshots. New/reversed/reconciled cash evidence affects subsequent positions and forecasts, not source transaction history.', 'A', FALSE, FALSE, FALSE, TRUE, 'cc2636ab-0e6b-50f1-b2d1-8a01ac81eaed', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('90df339a-cdfb-5155-90f9-149224eb961b', 'cc2636ab-0e6b-50f1-b2d1-8a01ac81eaed', 'fd81e359-be3b-5627-a0ba-078b152ffdd8', 'Cash Position', 'Shows one Cash Position at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Bank Account is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
