VALUES ('58a925c9-4a28-5efd-abe6-0b7d33158f94', 'fa633387-3b8e-51d5-af12-01472d59b222', '788538d1-bdd5-53bb-b73b-8f15268fb3b5', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Pricing Evidence', 'Snapshot of material pricing inputs used to determine the invoice line amount. Preserves source, effective date, and approved commercial context needed to reproduce pricing even when master data changes. Supports audit, dispute resolution, recalculation, credit calculation and integration. Links the invoice result to the effective transaction price without making the posted invoice depend on mutable pricing master data.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bdbe6e0e-8e88-5825-b8dc-7e755cb0f0a7', 'fa633387-3b8e-51d5-af12-01472d59b222', '87eaa8f4-4f64-59d1-9fd0-84cfe131a2ac', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Discount Evidence', 'Snapshot of the discount policy inputs and result used on the invoice line. Preserves the applied discount rule/version, method, base, rate or fixed amount, and resulting discount. Supports audit and prevents later DiscountRule changes from altering historical calculations or credits. Provides reproducible discount calculation evidence.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ce9a3077-ea62-5932-980a-4e9155b02c7c', 'fa633387-3b8e-51d5-af12-01472d59b222', 'ebec2e44-0676-5339-8223-6dd4ff929b8b', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Tax Evidence', 'Snapshot of the tax determination inputs and result used on the invoice line. Preserves tax rule/version, jurisdiction, rate, taxable base, rounding and calculated tax. Supports tax audit, compliance, dispute resolution and credit-note tax calculation. Prevents later TaxRule changes from rewriting posted invoice tax.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9f4b5995-46cd-596a-9bb5-21efffbe6df1', 'fa633387-3b8e-51d5-af12-01472d59b222', '0373c7d1-2f34-55a0-977e-9f0a91b3dc72', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Description', 'Human-readable description of the original billed line. Describes the billed good or service. Used on documents and audit. Complements Product and source transaction references. Supports document presentation. Optional descriptive context. Up to 1000 characters.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3c49db20-3ca1-5396-9759-835b8cbe7f48', 'fa633387-3b8e-51d5-af12-01472d59b222', '9aa8cc3e-2916-515f-8fef-b86889c44d47', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Matching Status', 'Procurement matching state of the invoice line. Indicates whether the line agrees with applicable purchase and receipt evidence. Used for accounts payable controls and reconciliation. Independent from CreditNote and SupplierCreditNote status; a credit may correct a posted line after matching. Controls matching approval before posting. Required — the record cannot be saved while this is empty.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('caa8933f-93db-5006-b910-3cee1b215989', 'fa633387-3b8e-51d5-af12-01472d59b222', '3fb7514d-6b06-5bf8-a91b-29b64cd89227', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Unit Of Measure', 'Unit in which the original quantity was billed. Defines measurement semantics for the historical quantity. Supports billing, fulfillment and return conversion. Provides source measurement context for eligible credits.', 150, 150, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ecc4e908-3607-5028-85dd-18b2d76d8798', 'fa633387-3b8e-51d5-af12-01472d59b222', '744590b5-3a1f-5535-8f2a-01abdc9d7663', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Invoice', 'Parent invoice containing the original claim line. Provides financial document context. Supports billing, settlement, adjustment and audit. Parent claim owns the line''s historical calculation. Required — the record cannot be saved while this is empty.', 160, 160, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6c9367e-27a2-5d90-98a0-6b114112c175', 'fa633387-3b8e-51d5-af12-01472d59b222', 'a364cdbe-c1d4-5e96-a528-13e1a6fb9d14', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Product', 'Product or service identified by the original invoice line. Identifies what was billed without making current product master data a live dependency of posted history. Supports billing, fulfillment and return traceability. Supplies source item context.', 170, 170, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2c25efca-8b45-5855-b5f3-e01c1cf59f27', 'fa633387-3b8e-51d5-af12-01472d59b222', 'bf378c75-e063-54e7-9c94-e76270a90fe3', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Purchase Order Line', 'Procurement line associated with a purchase invoice line. Connects payable billing to the original procurement commitment. Supports three-way matching and supplier-return traceability. Supplies source procurement evidence.', 180, 180, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
