VALUES ('5c7897ce-8576-5974-b585-220395283562', 'fa633387-3b8e-51d5-af12-01472d59b222', 'f095d7da-8940-58a7-94db-9cefa8c6b988', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Sales Order Line', 'The SalesOrderLine this InvoiceLine belongs to.', 190, 190, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
