-- --------------------------------------------------------------------------
-- Payment Allocation (bus_payment_allocation)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('51f3e21a-9519-5af5-843a-aa1b902d9404', 'bus_payment_allocation', 'Payment Allocation', 'Provides the controlled bridge between a Payment event and an Invoice claim. Payment says money moved; Invoice says money is owed; PaymentAllocation says exactly how much of that payment satisfies that claim. Central to receivables, payables, collections, payment reconciliation, bank reconciliation, refunds, reallocation, and accounting. Payment supplies source funds. Invoice supplies target obligation. Currency defines denominations. ExchangeRate converts denominations when required. Invoice derives settlement projections from active allocations. Payment received or posted → validate available unapplied amount → select Invoice → compare currencies → select approved ExchangeRate if required → calculate target invoice amount → apply rounding policy → activate PaymentAllocation → update Invoice amountSettled/amountOutstanding/status → reconcile with bank and accounting evidence. Draft allocation → validation → active settlement → optional reversal/cancellation → corrected allocation if needed. Historical allocations are never silently rewritten. A EUR 5,000 Payment is applied to a USD invoice using an approved EUR-to-USD ExchangeRate. paymentAmount remains EUR 5,000, invoiceAmount records the USD claim value satisfied, ExchangeRate preserves the conversion evidence, and any rounding adjustment is explicit. The Invoice is not marked paid until its active allocations satisfy its outstanding amount.', 'A', FALSE, FALSE, FALSE, TRUE, 'e6875e36-1428-5147-a5e3-062d966a3975', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d44e3d82-88d9-5c90-b238-f6bad91cfc53', 'e6875e36-1428-5147-a5e3-062d966a3975', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'Payment Allocation', 'Shows one Payment Allocation at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Payment, Invoice, Exchange Rate and Currency are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d0436011-4785-58d6-816a-1605b509015e', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'id', 'Id', 'Stable identity of the settlement allocation. Identifies the application of payment value to a claim independently of the Payment and Invoice identities. Used for reconciliation, audit, reversal, reallocation, and settlement projections. Payment identifies money received or sent; Invoice identifies the claim; PaymentAllocation connects the two. Provides the auditable settlement bridge used to derive Invoice amountSettled and amountOutstanding. Required for traceable allocation evidence.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a5a174a4-1616-5b5e-ac81-1d6208984659', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'payment_id', 'Payment', 'Payment from which the allocated settlement amount originates. Identifies the cash or settlement event being applied. Supports payment reconciliation, bank matching, and settlement audit. The allocation cannot create or replace the underlying Payment event. Supplies the source monetary amount and payment currency for allocation. Required to trace settlement to its source.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dfff61f1-37f2-5db7-8c5c-c7f55c427edd', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'invoice_id', 'Invoice', 'Invoice claim to which the payment is applied. Identifies the financial obligation being reduced by the allocation. Supports receivables/payables settlement, aging, statements, and reconciliation. The allocation reduces the claim; it does not change the original Invoice total. Supplies the target claim and invoice currency for settlement comparison. Required to identify the settlement target.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c64269ff-4f1e-5c61-8246-6e03c2a909e4', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'payment_amount', 'Payment Amount', 'Portion of the Payment amount consumed by this allocation in the Payment currency. Represents how much of the source payment is assigned to this claim. Supports remaining-payment calculation and reconciliation to the Payment. Must use the Payment currency and must not exceed the unapplied source payment amount under policy. Establishes the source-side settlement quantity before any cross-currency conversion. Required for allocation calculation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e92c581e-d4b3-5d90-b423-127803f7639b', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'invoice_amount', 'Invoice Amount', 'Amount of the Invoice claim satisfied by this allocation in the Invoice currency. Represents the claim-side effect of the allocation. Drives Invoice amountSettled and amountOutstanding projections. May differ numerically and in currency from paymentAmount when an approved ExchangeRate is used. Supplies the target-side settlement value applied to the claim. Required for deterministic claim settlement.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7f081560-4788-530d-92ab-6d870e8b092a', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'exchange_rate_id', 'Exchange Rate', 'Exchange-rate record used when Payment and Invoice currencies differ. Preserves the exact conversion context used to translate payment currency into invoice currency. Supports audit, reconciliation, accounting, and reproducibility of cross-currency settlement. Required for cross-currency allocation and normally absent when currencies are identical. Connects paymentAmount to invoiceAmount through an approved conversion rule. Optional when source and target currencies are identical.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cf4fb70b-ff5b-5078-abf1-764bc2c99813', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'allocated_at', 'Allocated At', 'Timestamp at which the allocation became effective. Establishes settlement chronology and supports period-sensitive reconciliation. Used for aging, accounting period determination, audit, and dispute investigation. Distinct from Payment creation time and bank clearing time. Determines when the Invoice settlement projection is changed. Required for settlement chronology.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f7b1a3d5-55d0-5af3-9cbe-7841d4e432f4', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'status', 'Status', 'Lifecycle state of the allocation. Indicates whether the allocation currently affects settlement or has been reversed/cancelled. Controls Invoice settlement projections, reconciliation, and audit. Invoice amountSettled must be derived from active allocations rather than every historical allocation record. ACTIVE affects settlement; REVERSED removes the allocation effect through a controlled correction; CANCELLED prevents activation. Required for controlled settlement state.', 1035, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('128cdfab-7634-5385-8620-f4375dc6f9d5', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'reversal_of_allocation_id', 'Reversal Of Allocation', 'Original allocation that this record reverses. Links a correction to the settlement evidence it negates. Supports audit, dispute resolution, reallocation, and accounting correction. A reversal is a new historical event and does not rewrite the original allocation. Enables controlled reversal followed by a corrected allocation. Optional for normal allocations.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b0e3c4ab-f6f6-5c2f-a039-a823001f1ce5', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'rounding_adjustment', 'Rounding Adjustment', 'Explicit rounding difference required to reconcile source and target settlement values under the approved conversion and currency precision policy. Represents a controlled rounding effect, not an unexplained difference in payment or invoice value. Used in cross-currency reconciliation and accounting adjustment. Must use an appropriate currency and remain within configured tolerance. Makes small conversion/precision differences explicit and auditable. Optional when no rounding adjustment is required.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('10d12f77-c384-59da-89d3-06c7a4800b71', '51f3e21a-9519-5af5-843a-aa1b902d9404', 'currency_id', 'Currency', 'The Currency this PaymentAllocation belongs to.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
