INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4032e99d-0ef3-508d-a496-018ffb818a0d', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'd0436011-4785-58d6-816a-1605b509015e', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Id', 'Stable identity of the settlement allocation. Identifies the application of payment value to a claim independently of the Payment and Invoice identities. Used for reconciliation, audit, reversal, reallocation, and settlement projections. Payment identifies money received or sent; Invoice identifies the claim; PaymentAllocation connects the two. Provides the auditable settlement bridge used to derive Invoice amountSettled and amountOutstanding. Required for traceable allocation evidence. Must be unique: a save is rejected if another Payment Allocation already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa5375b0-95c8-5829-809f-1b4d2885c215', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'a5a174a4-1616-5b5e-ac81-1d6208984659', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Payment', 'Payment from which the allocated settlement amount originates. Identifies the cash or settlement event being applied. Supports payment reconciliation, bank matching, and settlement audit. The allocation cannot create or replace the underlying Payment event. Supplies the source monetary amount and payment currency for allocation. Required to trace settlement to its source. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('55203f4e-791c-5c4d-938f-4b6a2cc10248', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'dfff61f1-37f2-5db7-8c5c-c7f55c427edd', '116ad2ee-ffb8-5c0c-aeb5-dc12c8dec856', 'Invoice', 'Invoice claim to which the payment is applied. Identifies the financial obligation being reduced by the allocation. Supports receivables/payables settlement, aging, statements, and reconciliation. The allocation reduces the claim; it does not change the original Invoice total. Supplies the target claim and invoice currency for settlement comparison. Required to identify the settlement target. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('43237fde-c9cd-57fe-974e-f4cbd0cdbc9d', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'c64269ff-4f1e-5c61-8246-6e03c2a909e4', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Payment Amount', 'Portion of the Payment amount consumed by this allocation in the Payment currency. Represents how much of the source payment is assigned to this claim. Supports remaining-payment calculation and reconciliation to the Payment. Must use the Payment currency and must not exceed the unapplied source payment amount under policy. Establishes the source-side settlement quantity before any cross-currency conversion. Required for allocation calculation. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b04c94c2-eb1e-5aa5-ab67-0580bd77921a', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'e92c581e-d4b3-5d90-b423-127803f7639b', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Invoice Amount', 'Amount of the Invoice claim satisfied by this allocation in the Invoice currency. Represents the claim-side effect of the allocation. Drives Invoice amountSettled and amountOutstanding projections. May differ numerically and in currency from paymentAmount when an approved ExchangeRate is used. Supplies the target-side settlement value applied to the claim. Required for deterministic claim settlement. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a52b337-f52b-5bfc-9487-8a3f04aa9ceb', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', '7f081560-4788-530d-92ab-6d870e8b092a', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Exchange Rate', 'Exchange-rate record used when Payment and Invoice currencies differ. Preserves the exact conversion context used to translate payment currency into invoice currency. Supports audit, reconciliation, accounting, and reproducibility of cross-currency settlement. Required for cross-currency allocation and normally absent when currencies are identical. Connects paymentAmount to invoiceAmount through an approved conversion rule. Optional when source and target currencies are identical.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f9d99762-6c46-554e-86b5-d0155d5c78a4', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'cf4fb70b-ff5b-5078-abf1-764bc2c99813', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Allocated At', 'Timestamp at which the allocation became effective. Establishes settlement chronology and supports period-sensitive reconciliation. Used for aging, accounting period determination, audit, and dispute investigation. Distinct from Payment creation time and bank clearing time. Determines when the Invoice settlement projection is changed. Required for settlement chronology. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4f4fca97-29ec-5b04-9bca-5f28315989fb', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'f7b1a3d5-55d0-5af3-9cbe-7841d4e432f4', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Status', 'Lifecycle state of the allocation. Indicates whether the allocation currently affects settlement or has been reversed/cancelled. Controls Invoice settlement projections, reconciliation, and audit. Invoice amountSettled must be derived from active allocations rather than every historical allocation record. ACTIVE affects settlement; REVERSED removes the allocation effect through a controlled correction; CANCELLED prevents activation. Required for controlled settlement state. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2b0660d7-0996-5c1f-9d46-b10340fe3ecd', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', '128cdfab-7634-5385-8620-f4375dc6f9d5', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Reversal Of Allocation', 'Original allocation that this record reverses. Links a correction to the settlement evidence it negates. Supports audit, dispute resolution, reallocation, and accounting correction. A reversal is a new historical event and does not rewrite the original allocation. Enables controlled reversal followed by a corrected allocation. Optional for normal allocations.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b42d0508-4167-5445-afe6-9928ca1a9aa6', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', 'b0e3c4ab-f6f6-5c2f-a039-a823001f1ce5', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Rounding Adjustment', 'Explicit rounding difference required to reconcile source and target settlement values under the approved conversion and currency precision policy. Represents a controlled rounding effect, not an unexplained difference in payment or invoice value. Used in cross-currency reconciliation and accounting adjustment. Must use an appropriate currency and remain within configured tolerance. Makes small conversion/precision differences explicit and auditable. Optional when no rounding adjustment is required.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6238e4d4-dd66-50db-b6e9-21e29c71587c', 'd44e3d82-88d9-5c90-b238-f6bad91cfc53', '10d12f77-c384-59da-89d3-06c7a4800b71', 'cd4dea54-825f-567c-bedd-f8e149f09fca', 'Currency', 'The Currency this PaymentAllocation belongs to.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_access (sys_access_id, sys_role_id, sys_table_id, sys_window_id, access_type_table, is_read_only, is_exclude, entity_type, is_active, created_by, updated_by, created_at, updated_at)
