VALUES ('decf7b4a-7ee9-5162-ae22-855b22b75a60', (SELECT sys_role_id FROM sys_role WHERE name = 'User'), '51f3e21a-9519-5af5-843a-aa1b902d9404', 'e6875e36-1428-5147-a5e3-062d966a3975', 'R', TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
