-- --------------------------------------------------------------------------
-- Credit Note Line (bus_credit_note_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('06f120cc-44b9-556b-a325-fb08a1bb956e', 'bus_credit_note_line', 'Credit Note Line', 'Represents one auditable financial adjustment detail and its source evidence. CreditNoteLine translates an eligible original invoice or return into a specific credited value while preserving historical source facts. Return credits, billing corrections, tax adjustments, customer concessions and audit. InvoiceLine is the original financial evidence; CustomerReturnLine is the reverse-fulfillment evidence; CreditNoteLine is the new financial result. Validate source → determine eligible quantity/value → apply return and pricing/tax policy → snapshot evidence → calculate line credit → approve → post through CreditNote. Corrections use reversal/replacement. Draft → calculated → approved → posted, with controlled reversal after posting. Three returned units are eligible for credit at the original transaction value. CreditNoteLine records quantity 3, preserves the source InvoiceLine and CustomerReturnLine, recalculates applicable tax, and contributes its total to CreditNote without changing the original invoice line.', 'A', FALSE, FALSE, FALSE, TRUE, '88634eaa-67df-5b93-be1e-cab32f218399', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9c3346d4-879a-551b-b71e-60f0500eb2b2', '88634eaa-67df-5b93-be1e-cab32f218399', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'Credit Note Line', 'Shows one Credit Note Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 7 fields marked with a red asterisk (*) must have a value before Save will accept the record. Invoice Line and Credit Note are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ab690b5-9289-541d-be15-da2a3d88c69a', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'id', 'Id', 'Immutable identity of the credit-note line. Identifies one financial adjustment detail independently of its source invoice or return. Used for accounting, audit, reconciliation, tax and correction workflows. Links the line to CreditNote while preserving distinct source InvoiceLine and CustomerReturnLine identities. Stable reference for calculation, posting and reversal. Required for traceability.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b226100b-2707-5549-9b25-c5e63d396989', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'line_number', 'Line Number', 'Business sequence number within the CreditNote. Orders the adjustment details for document presentation and audit. Used for documents, reconciliation and integrations. Unique within the parent CreditNote and independent of original InvoiceLine.lineNumber. Supports deterministic document reconstruction. Required for line identification.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('672dfa52-809f-5fdd-b4c2-83e324ce9acb', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'quantity', 'Quantity', 'Quantity being financially credited when the adjustment is quantity-based. Represents the credited quantity, which may be less than or equal to the returned quantity or originally billed quantity. Used for return credits, quantity corrections and reconciliation. Must reconcile with eligible source InvoiceLine and CustomerReturnLine quantities. Feeds line valuation where credit is quantity-derived. Optional for purely monetary corrections.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('43e43e93-1226-5206-99c9-c21f992f075d', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'unit_price', 'Unit Price', 'Transaction-time unit value used to calculate the credit where applicable. Preserves the original or policy-approved value rather than using mutable current pricing. Supports reproducibility, dispute resolution and audit. Should reconcile with source InvoiceLine pricing evidence or authorized return-credit policy. Supplies valuation evidence for quantity-based credits. Optional for fixed monetary adjustments.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('77f4a35c-da82-53ad-aef5-24d485d978e3', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'subtotal', 'Subtotal', 'Pre-tax monetary credit represented by this line. The line''s financial base before credited tax. Used for CreditNote calculation, accounting and reconciliation. Must reconcile with quantity, unitPrice, discounts and source evidence where applicable. Feeds taxable amount and total line credit. Required for deterministic financial calculation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('229e4300-a6a1-53ae-a7fb-89c3daace6eb', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'discount_amount', 'Discount Amount', 'Discount component included in determining the credited line value. Preserves the applicable discount treatment from the original transaction or return policy. Used for reconciliation and tax calculation. Must not be confused with a new settlement discount. Determines the credited taxable base according to policy. Required, including zero when no discount applies.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('faa5cdf7-9037-5dbb-8819-eab10f73fd57', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'taxable_amount', 'Taxable Amount', 'Taxable base of the credited line. Amount to which applicable tax treatment is applied for the credit. Used for tax reporting and accounting. Must reconcile with original InvoiceLine tax treatment or authorized correction policy. Feeds credited tax calculation. Required for tax determinism.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('341ea865-e9c4-5711-9b70-1822be084ace', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'tax_amount', 'Tax Amount', 'Tax amount reversed or credited on this line. Represents the tax consequence of the credited value. Used for tax reporting, accounting and reconciliation. Must reconcile with applicable TaxRule and source invoice tax evidence. Contributes to the line''s total credit. Required, including zero when no tax applies.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4a0583a-96fc-5709-adb3-f6599d776096', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'total_amount', 'Total Amount', 'Total credit represented by this line including applicable tax. Financial reduction attributable to this specific adjustment detail. Aggregated into CreditNote.totalAmount and used for accounting/application. Does not mutate the original InvoiceLine amount. Provides authoritative line contribution to the CreditNote total. Required for document reconciliation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('174ad2ab-95f7-5fd9-9da4-bb1f076c7a99', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'pricing_evidence', 'Pricing Evidence', 'Snapshot of material valuation inputs used for the credited amount. Preserves original price, source, effective date or authorized override required to reproduce the credit. Supports audit and dispute resolution. Connects valuation to original InvoiceLine evidence without making the credit depend on current price master data. Provides historical calculation evidence.', 28, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
