VALUES ('75c39506-92fd-53b1-bf8e-94db6687b5be', '06f120cc-44b9-556b-a325-fb08a1bb956e', 'invoice_line_id', 'Invoice Line', 'Original billed line from which the credit is derived or corrected. Preserves the financial claim basis without modifying its historical values. Supports return credit, billing correction, tax correction and audit. Supplies eligible quantity, price, discount and tax evidence.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
