UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'foundation') WHERE table_name IN ('bus_party', 'bus_person', 'bus_organization', 'bus_party_role', 'bus_party_relationship', 'bus_legal_entity', 'bus_business_unit', 'bus_department', 'bus_address', 'bus_contact_point', 'bus_location', 'bus_country', 'bus_language', 'bus_currency', 'bus_exchange_rate', 'bus_unit_of_measure', 'bus_calendar', 'bus_attachment', 'bus_journal_entry_line', 'bus_budget_line', 'bus_invoice_line', 'bus_payment_allocation', 'bus_credit_note_line', 'bus_purchase_order_line', 'bus_sales_order_line', 'bus_bank_account', 'bus_asset', 'bus_product');
