UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'accounts-payable') WHERE table_name IN ('bus_supplier', 'bus_purchase_order');
UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'accounts-receivable') WHERE table_name IN ('bus_customer', 'bus_sales_order');
UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'budgeting-and-planning') WHERE table_name IN ('bus_budget', 'bus_forecast', 'bus_scenario', 'bus_cost_center', 'bus_profit_center', 'bus_variance');
UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'finance-and-accounting-records') WHERE table_name IN ('bus_ledger', 'bus_fiscal_period', 'bus_payment_instruction', 'bus_credit_note', 'bus_credit_note_application', 'bus_tax_code', 'bus_tax_jurisdiction', 'bus_tax_rate', 'bus_tax_registration', 'bus_tax_rule', 'bus_tax_transaction', 'bus_billing_cycle', 'bus_charge', 'bus_subscription', 'bus_subscription_plan', 'bus_usage_record', 'bus_asset_class', 'bus_asset_acquisition', 'bus_asset_depreciation', 'bus_asset_disposal', 'bus_asset_transfer', 'bus_foreign_exchange_transaction', 'bus_cash_position', 'bus_interest');
UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'foundation') WHERE sys_category_id IS NULL AND table_name LIKE 'bus\_%';
